  Project.init({
    name: DataTypes.STRING,
    description: DataTypes.STRING,
    startDate: DataTypes.STRING,
    customerID: DataTypes.INTEGER

  }, {
    sequelize,
    modelName: 'Project',
  });
  return Project;
};

